import pandas as pd
import numpy as np

# Load all available experiments
dfs = {}
for i in range(1, 6):
    dfs[i] = pd.read_csv(f"experiment_{i}_csv")
    print(f"\n--- Experiment {i} ---")
    print(dfs[i].columns.tolist())
    print(dfs[i].describe().loc[dfs[i].describe().index])

# Extract HarvestBiomass and any control variables
biomass_data = []
for i, df in dfs.items():
    if 'HarvestBiomass' in df.columns:
        for _, row in df.iterrows():
            rec = {'Exp': i, 'Biomass': row['HarvestBiomass']}
            for col in df.columns:
                if col not in ['HarvestBiomass']:
                    rec[col] = row[col]
            biomass_data.append(rec)

df_all = pd.DataFrame(biomass_data)
print("\n--- Combined Data ---")
print(df_all.head(20))
print("\nUnique values for potential controls:")
for col in df_all.columns:
    if col != 'Biomass':
        print(f"{col}: {df_all[col].unique()}")

import pandas as pd
import numpy as np
from scipy import stats
import os

# Load all experiments
dfs = {}
for i in range(1, 7):
    fpath = f'experiment_{i}_csv'
    dfs[f'exp{i}'] = pd.read_csv(eval(fpath))

print("=== COLUMNS ACROSS ALL EXPERIMENTS ===")
for k, df in dfs.items():
    print(f"{k}: {list(df.columns)}")

print("\n=== ALL EXPERIMENT MEANS ===")
for k, df in dfs.items():
    print(f"\n{k}:")
    for col in df.columns:
        if df[col].dtype in ['float64', 'int64']:
            print(f"  {col}: mean={df[col].mean():.2f} std={df[col].std():.2f}")

print("\n=== FULL CORRELATION MATRIX (Baseline Exp1) ===")
print(dfs['exp1'].corr(numeric_only=True).round(3))

print("\n=== COMPARING CONDITION-LEVEL VARIABLES ACROSS EXPERIMENTS ===")
for k, df in dfs.items():
    cond_vars = [c for c in df.columns if c in ['AerationLevel','StockingDensity','pHLevel','FeedProteinPct','FeedRate','FiltrationLevel']]
    for cv in cond_vars:
        if cv in df.columns:
            vals = df[cv].dropna()
            if len(vals) > 0:
                print(f"  {k} {cv}: {vals.iloc[0]:.1f}")

print("\n=== AMMONIA LEVELS BY EXPERIMENT ===")
for k, df in dfs.items():
    if 'AmmoniaLevel' in df.columns:
        print(f"  {k}: Ammonia mean={df['AmmoniaLevel'].mean():.2f}")

print("\n=== TEMPERATURE LEVELS BY EXPERIMENT ===")
